def _parse(version):
    """Parse a version string into (major, minor, patch, prerelease_ids, build).

    Build metadata is returned but ignored for ordering.
    """
    s = version.strip()
    # Split off build metadata (everything after the first '+').
    if '+' in s:
        s, _build = s.split('+', 1)
    else:
        _build = None
    # Split off pre-release (everything after the first '-').
    if '-' in s:
        core, pre = s.split('-', 1)
        prerelease = pre.split('.') if pre != '' else []
    else:
        core = s
        prerelease = []
    parts = core.split('.')
    while len(parts) < 3:
        parts.append('0')
    major, minor, patch = (int(parts[0]), int(parts[1]), int(parts[2]))
    return major, minor, patch, prerelease


def _identifier_key(ident):
    # Numeric identifiers sort before alphanumeric ones; numerics by value,
    # alphanumerics by ASCII order.
    if ident.isdigit():
        return (0, int(ident))
    return (1, ident)


def _prerelease_key(prerelease):
    # A version without a pre-release ranks above one with a pre-release.
    if not prerelease:
        return (1,)
    return (0, tuple(_identifier_key(i) for i in prerelease))


def _sort_key(version):
    major, minor, patch, prerelease = _parse(version)
    return (major, minor, patch, _prerelease_key(prerelease))


def sort_versions(vs):
    """Return a new list of SemVer strings sorted lowest precedence first.

    Ties (including build-metadata-only differences) preserve input order.
    """
    return sorted(vs, key=_sort_key)
